  function locationCards(){return(state.locations||[]).map((l,i)=>`<article class="location-card" data-location="${esc(l.id)}"><div class="character-card-top"><b>Место ${i+1}</b><button class="btn-quiet" data-location-action="delete" data-id="${esc(l.id)}" type="button">Удалить</button></div><div class="location-fields"><input class="input" data-location-field="name" value="${esc(l.name||'')}" placeholder="Название: кафе, дом Саоюй"><textarea data-location-field="description" placeholder="Описание локации, постоянная обстановка">${esc(l.description||'')}</textarea><textarea data-location-field="referencePrompt" placeholder="Промпт для референса места">${esc(l.referencePrompt||'')}</textarea><label class="character-reference"><input type="file" data-location-ref accept="image/*"><span>${l.referenceName?'Заменить изображение места':'Загрузить референс места'}</span></label><button class="btn-quiet" data-location-action="generate" data-id="${esc(l.id)}" type="button">Создать референс по описанию</button><span class="character-reference-name">${esc(l.referenceName||'Референс не добавлен')}</span><div class="location-reference-preview" data-location-preview="${esc(l.id)}"></div></div></article>`).join('')||'<div class="script-empty">Добавьте место из учебника, чтобы сохранять его визуальный образ между сценами.</div>'}
