  function decorateDialogues(){const root=document.querySelector('#view');if(!root?.querySelector('.script-studio'))return;for(const line of root.querySelectorAll('.script-line')){let input=line.querySelector('[data-line-field="character"]');if(!input)continue;const value=input.value;let select=input;if(input.tagName!=='SELECT'){select=document.createElement('select');select.className='input';select.dataset.lineField='character';select.setAttribute('aria-label','Персонаж реплики');input.replaceWith(select)}const names=(state.characters||[]).map(c=>c.name).filter(Boolean);if(value&&!names.includes(value))names.unshift(value);const unique=[...new Set(names)],sig=JSON.stringify(unique);if(select.dataset.optionsSig!==sig){select.innerHTML='<option value="">Выбрать персонажа</option>'+unique.map(n=>'<option value="'+esc(n)+'">'+esc(n)+'</option>').join('');select.dataset.optionsSig=sig}select.value=value;const selected=(state.characters||[]).find(c=>c.name===select.value);const head=line.querySelector('.script-line-head');let avatar=head?.querySelector('.script-character-avatar');if(head&&!avatar){avatar=document.createElement('img');avatar.className='script-character-avatar';avatar.alt='';head.prepend(avatar)}if(avatar){avatar.dataset.avatarName=selected?.name||'';if(selected&&!avatar.src)loadOneAvatar(selected,avatar);if(!selected)avatar.removeAttribute('src')}}}
  function drawCandidates(){const list=document.querySelector('#candidateList');if(!list)return;list.innerHTML=(state.candidates||[]).map((c,i)=>`<article class="candidate-card" data-candidate="${i}"><div class="script-section-title"><h3>Вариант ${i+1}: ${esc(c.title||'Новая версия')}</h3><button class="btn" data-candidate-action="apply" data-index="${i}" type="button">Добавить в текущую сцену</button></div><div class="candidate-grid"><label>Сюжетный такт<textarea data-candidate-field="story_beat">${esc(c.story_beat)}</textarea></label><label>Целевые слова<textarea data-candidate-field="target_words">${esc(c.target_words)}</textarea></label><label>Краткая учебная функция<textarea data-candidate-field="learning_goal">${esc(c.learning_goal)}</textarea></label><label>Оригинальная разговорная реплика<textarea data-candidate-field="natural_alternative">${esc(c.natural_alternative)}</textarea></label><label class="full">Диалог и разбор<textarea data-candidate-field="dialogue_text">${esc((c.dialogue||[]).map(d=>`${d.character||'Персонаж'}: ${d.hanzi||''} (${d.pinyin||''}) — ${d.translation||''}${d.note?' · '+d.note:''}`).join('\n'))}</textarea></label><label class="full">Промпт генерации кадра<textarea data-candidate-field="storyboard_prompt">${esc(c.storyboard_prompt)}</textarea></label></div><div class="script-mini">Проверьте лексику, тональность и пиньинь перед добавлением.</div></article>`).join('');}
