    const sig=[blob.size,blob.type,p.videoModel||''].join(':');
    if(p.webbookClipSent===sig){const r=await fetch('/local/webbook/books/'+id+'/pages/'+n+'/clip').then(r=>r.json()).catch(()=>({}));if(r.size===blob.size){await syncClipPoster(p,i,blob).catch(()=>{});return false}}
