        sel.addEventListener('change',()=>{state.webbookSpeakers||={};if(sel.value)state.webbookSpeakers[sel.dataset.webbookSpeaker]=sel.value;else delete state.webbookSpeakers[sel.dataset.webbookSpeaker];saveState();renderElectronicPage(i)});
