      fig.querySelectorAll('[data-face-outfit]').forEach(b=>b.addEventListener('click',()=>{p.outfit||={};p.outfit[c.id]=b.dataset.faceOutfit==='ref';saveState();fig.querySelectorAll('[data-face-outfit]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));setPageImageStatus(i,c.name+': '+(p.outfit[c.id]?'одежда с референса':'одежда как на картинке')+' — учтётся при следующем первом кадре.')}));
