      const list=(all||[]).filter(e=>e.kind===kind&&e.file&&(!onlyPage||Number(e.page)===Number(p.pageNumber))&&(!onlyGood||Number(e.rating)>=4)).sort((a,b)=>(b.no||0)-(a.no||0));
