    if(!file){root.innerHTML='<div class="page-source-placeholder">Исходная страница недоступна. Загрузите PDF или скан этой страницы.</div>';return}
    if(previewUrl)URL.revokeObjectURL(previewUrl);
    previewUrl=URL.createObjectURL(file);
