  // Clip settings, from what the chosen video model offers, kept per page:
  // length ("auto" = about 3 s a line of the page's dialogue, at least 10 s),
  // resolution (auto = 720p where offered, a sharp and affordable middle) and
  // frame format (auto = 16:9, the lesson page's photo slot).
  const videoMeta=()=>(models.video||[]).find(x=>x.id===document.querySelector('#pageVideoModel')?.value);
  function clipDurations(){return (videoMeta()?.supported_durations||[]).map(Number).filter(Number.isFinite).sort((a,b)=>a-b)}
  // About 3 s a line plus a beat at each end: with too little time a model drops a line (p18: the teacher's).
  function linesSeconds(p){const n=(p.brief?.dialogue||[]).length;return n?2+n*3:0}
  function autoDuration(p){let json={};try{json=JSON.parse(p.videoPromptJson||'{}')}catch{}return Math.max(10,Number(json.durationSeconds)||10,linesSeconds(p))}
  const autoResolution=list=>list.includes('720p')?'720p':list[0]||'';
  const autoAspect=list=>list.includes('16:9')?'16:9':list[0]||'';
