  // The page's own illustration (cut by «PDF → Web»), the largest one when there are several.
  async function pageArt(p){
    const got=await pageLayout(Number(p.pageNumber)).catch(()=>null),blocks=got?.layout?.blocks||[];let best=null;
    blocks.forEach((b,k)=>{const url=got.assets['img-'+k],area=(b.box?.w||0)*(b.box?.h||0);if(b.type==='image'&&url&&(!best||area>best.area))best={url,area,alt:b.alt||''}});
    if(!best)return null;try{const r=await fetch(best.url);return r.ok?{blob:await r.blob(),alt:best.alt}:null}catch{return null}
  }
  // The gallery keeps a few variants: the oldest one that is neither chosen
  // nor placed on the electronic page goes first.
  const GALLERY_MAX=6;
  function imageInUse(p,id){return p.activeImageId===id||(p.electronicBlocks||[]).some(b=>b.imageId===id)}
  async function dropGalleryImage(p,id){const k=(p.images||[]).findIndex(x=>x.id===id);if(k<0){if(id==='legacy')await deleteFile('page-image:'+p.id).catch(()=>{});return}const [x]=p.images.splice(k,1);if(p.activeImageId===id)p.activeImageId=p.images[p.images.length-1]?.id||'';for(const b of p.electronicBlocks||[])if(b.imageId===id)b.imageId=p.activeImageId||'';await deleteFile(x.key||('page-image:'+p.id+':'+x.id)).catch(()=>{})}
  async function trimGallery(p){let n=0;while((p.images||[]).length>GALLERY_MAX){const x=p.images.find(x=>!imageInUse(p,x.id));if(!x)break;await dropGalleryImage(p,x.id);n++}if(n)saveState();return n}
  // A picture shown large next to the speakers' portraits, to check the faces against the references.
  async function openFrameViewer(i,key,title){
    const p=state.pages[i],blob=await getStoredFile(key).catch(()=>null);if(!p||!blob)return;
    document.querySelector('.frame-viewer')?.remove();
    const urls=[],url=b=>{const u=URL.createObjectURL(b);urls.push(u);return u};
    const box=document.createElement('div');box.className='frame-viewer';box.setAttribute('role','dialog');box.setAttribute('aria-label',title);
    const main=document.createElement('div');main.className='frame-viewer-main';
    const img=document.createElement('img');img.src=url(blob);img.alt=title;img.title='Нажмите, чтобы смотреть в полном размере';
    img.addEventListener('click',()=>main.classList.toggle('actual'));main.append(img);
    const side=document.createElement('aside');side.className='frame-viewer-refs';
    const head=document.createElement('div');head.className='frame-viewer-head';
    const h=document.createElement('strong');h.textContent=title+' · стр. '+p.pageNumber;
    const close=document.createElement('button');close.type='button';close.className='btn-quiet';close.textContent='Закрыть ✕';
    head.append(h,close);side.append(head);
    let count=0;
    const art=p.frameFromArt===false?null:await pageArt(p);
    if(art){const fig=document.createElement('figure'),im=document.createElement('img'),cap=document.createElement('figcaption');im.src=url(art.blob);im.alt=art.alt;im.className='frame-viewer-art';cap.textContent='Рисунок со страницы';fig.append(im,cap);side.append(fig)}
    for(const c of pageSpeakers(p)){
      const fig=document.createElement('figure'),row=document.createElement('div');row.className='frame-viewer-pair';
      for(const [k,label] of [['character:','лицо'],['character-body:','полный рост']]){const f=await getStoredFile(k+c.id).catch(()=>null);if(!f)continue;const im=document.createElement('img');im.src=url(f);im.alt=(c.name||'')+', '+label;im.title=label;row.append(im);count++}
      const cap=document.createElement('figcaption');cap.textContent=c.name||c.id;fig.append(row,cap);side.append(fig);
    }
    if(!count){const none=document.createElement('p');none.textContent='У героев этой страницы нет портретов-референсов — сравнивать не с чем.';side.append(none)}
    box.append(main,side);document.body.append(box);
    const done=()=>{box.remove();urls.forEach(u=>URL.revokeObjectURL(u));document.removeEventListener('keydown',onKey,true)};
    const onKey=e=>{if(e.key==='Escape'){e.stopPropagation();done()}};
    close.addEventListener('click',done);box.addEventListener('click',e=>{if(e.target===box)done()});document.addEventListener('keydown',onKey,true);close.focus();
  }
