    let staticHit=null;for(const m of description.matchAll(CAM)){const before=description.slice(Math.max(0,m.index-35),m.index),near=description.slice(Math.max(0,m.index-70),m.index+m[0].length+70);if(NEG.test(before))continue;if(TARGET.test(near)){staticHit=near.replace(/\s+/g,' ').trim();break}}
