    const allowed=description.replace(/(?:\bno\b|\bnot\b|\bnever\b|\bwithout\b|\bdon't\b|\bavoid\b|(?<![а-яё])(?:без|не|нет)(?![а-яё]))[^.;:\n]{0,60}?(?:english|английск[а-яё]*)(?:[\s,]*(?:or|and|или|и|no|nor)?[\s,]*(?:\w+\s){0,2}(?:speech|dialogue|речи|речь|реплик[а-яё]*))?/gi,' ')
      // A ban that comes after the phrase is a ban too: «Английская речь запрещена», «English is not allowed».
      .replace(/(?:english|английск[а-яё]*)[^.;\n]{0,40}?(?:forbidden|prohibited|banned|not allowed|not permitted|запрещ[а-яё]*|нельзя|недопустим[а-яё]*|не допуска[а-яё]*|не разреш[а-яё]*|исключен[а-яё]*)/gi,' ');
